import { useState } from "react";
import { useNavigate } from "react-router-dom";

function LoginPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState("");

  function signIn(event) {
    event.preventDefault();
    if (!email.trim() || !password) {
      setMessage("Enter your email address and password to continue.");
      return;
    }
    navigate("/");
  }

  return <main className="login-page">
    <style>{styles}</style>
    <section className="login-brand-panel">
      <div className="brand-orb" /><div className="brand-rings" />
      <div className="brand-copy"><p>PAYROLL AUTOMATION SYSTEM</p><span /><h1>Simple, secure<br />payroll management.</h1><div>Manage the payroll workflow from roster data through approval in one place.</div></div>
      <footer>Payroll Automation System<br />Version 1.0</footer>
    </section>
    <section className="login-form-panel">
      <form className="login-card" onSubmit={signIn}>
        <header><h2>Welcome back</h2><p>Sign in to continue to your account.</p></header>
        {message && <div className="login-message">{message}</div>}
        <label>Email address<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="Enter your email" autoComplete="email" /></label>
        <label>Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" placeholder="Enter your password" autoComplete="current-password" /></label>
        <button type="submit">Sign in <span>&rarr;</span></button>
        <p className="login-note">Demo screen: any non-empty email and password opens the dashboard.</p>
      </form>
    </section>
  </main>;
}

const styles = `
