import { BrowserRouter, Routes, Route, Link, useLocation } from "react-router-dom";
import DashboardPage from "./pages/DashboardPage";
import LoginPage from "./pages/LoginPage";
import RosterSyncPage from "./pages/RosterSyncPage";
import TimesheetValidationPage from "./pages/TimesheetValidationPage";
import PayrollCalcPage from "./pages/PayrollCalcPage";
import ApprovalPage from "./pages/ApprovalPage";
import PaymentPage from "./pages/PaymentPage";

function AppContent() {
  const location = useLocation();
  const showNavigation = location.pathname !== "/login";

  return (
    <>
      {showNavigation && <nav style={{ display: "flex", flexWrap: "wrap", gap: "10px", alignItems: "center", padding: "14px 28px", borderBottom: "1px solid #e5e7eb", background: "#fff", fontFamily: "Inter, Segoe UI, sans-serif" }}>
        <Link to="/" style={{ color: "#7a0000", fontWeight: 800, marginRight: "10px", textDecoration: "none" }}>Payroll Automation</Link>
        <Link to="/roster">UC-001 Roster</Link><Link to="/timesheets">UC-002 Timesheets</Link><Link to="/payroll">UC-003 Payroll</Link><Link to="/approvals">UC-004 Approvals</Link><Link to="/payments">UC-005 Payments</Link>
        <Link to="/login" style={{ marginLeft: "auto" }}>Sign out</Link>
      </nav>}
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/" element={<DashboardPage />} />
        <Route path="/roster" element={<RosterSyncPage />} />
        <Route path="/timesheets" element={<TimesheetValidationPage />} />
        <Route path="/payroll" element={<PayrollCalcPage />} />
        <Route path="/approvals" element={<ApprovalPage />} />
        <Route path="/payments" element={<PaymentPage />} />
      </Routes>
    </>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;
